<?php session_start(); ?><!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Xander Zombie Studio</title><style>
*{box-sizing:border-box}body{margin:0;background:#0e0e0e;color:#eee4cb;font-family:Arial,Helvetica,sans-serif}.studio{min-height:100vh;padding:3vh 3vw;background:radial-gradient(circle at 18% 20%,#4c594955,#111 35%,#090909 85%)}.mast{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:8px solid #eee4cb;padding-bottom:14px}.mast h1{font:900 clamp(34px,6vw,76px)/.85 Arial;margin:0}.mast small{letter-spacing:.2em}.grid{display:grid;grid-template-columns:1fr 1fr;gap:2vw;margin-top:2vw}.box{border:7px solid #eee4cb;background:#171717;padding:22px;box-shadow:10px 10px 0 #59634f}.box h2{font-size:26px;margin:0 0 12px}.field,textarea{width:100%;background:#0d0d0d;color:#eee4cb;border:2px solid #7d846f;padding:11px;font:15px/1.45 ui-monospace,monospace;margin:7px 0}textarea{min-height:180px;resize:vertical}.drop{border:3px dashed #8f987d;padding:22px;text-align:center;margin:10px 0;background:#101410}.btns{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}.btn{background:#e9dec2;color:#111;border:4px solid #111;padding:10px 15px;font-weight:900;cursor:pointer;box-shadow:4px 4px 0 #68705d;text-decoration:none}.btn.dark{background:#40503e;color:#f2e9d1}.btn:disabled{opacity:.4;cursor:not-allowed}.status{min-height:26px;margin-top:12px;font:13px ui-monospace;color:#aeb998}.login{max-width:480px;margin:13vh auto}.hidden{display:none}.plan{white-space:pre-wrap;min-height:440px}.preview{border:7px solid #111;background:#d7ceb7;color:#111;min-height:280px;padding:18px}.preview img{width:100%;display:block;border:5px solid #111}.panelcard{border:4px solid #111;margin:10px 0;padding:11px;background:#eee2c5}.panelcard b{display:block}.badge{display:inline-block;border:2px solid #89927d;padding:4px 7px;margin-right:6px;font-size:10px}.danger{color:#d68f7d}.source{font-size:11px;color:#9ea68e;line-height:1.6}@media(max-width:820px){.grid{grid-template-columns:1fr}.mast{align-items:flex-start;flex-direction:column;gap:9px}.studio{padding:2vh 4vw}.box{border-width:5px}}
</style></head><body><main class="studio"><header class="mast"><div><small>PRIVATE CREATOR ROOM</small><h1>XANDER ZOMBIE<br>COMIC ENGINE</h1></div><div>PHOTOS + MEMES + PROMPTS → CANON → COMIC</div></header><section id="login" class="login box"><h2>OPEN THE STUDIO</h2><input id="password" class="field" type="password" placeholder="password"><button id="loginBtn" class="btn">UNLOCK</button><div id="loginStatus" class="status"></div></section><section id="workspace" class="grid hidden"><div class="box"><h2>1 // THROW SOMETHING AT IT</h2><p>Photo, meme, screenshot, half a joke, or a sentence. The writer checks Xander's existing canon before making the next episode.</p><textarea id="prompt" placeholder="Example: Xander has to take school picture day after losing an ear, but he is way more worried about his mom seeing the report card."></textarea><label class="drop">DROP IMAGES / MEMES / PHOTOS HERE<input id="files" type="file" accept="image/*" multiple></label><div class="btns"><button id="intake" class="btn">MAKE EPISODE DRAFT</button><button id="clear" class="btn dark">CLEAR DESK</button></div><div id="status" class="status"></div><p class="source">Source uploads stay in the private studio. Published episodes contain the approved script and generated art, not the raw private uploads.</p></div><div class="box"><h2>2 // WRITER'S ROOM</h2><textarea id="plan" class="plan" placeholder="Generated structured episode plan appears here as editable JSON."></textarea><div class="btns"><button id="save" class="btn dark" disabled>SAVE EDITS</button><button id="render" class="btn dark" disabled>GENERATE COMIC PAGE</button><button id="publish" class="btn" disabled>PUBLISH TO CANON</button></div><div id="draftStatus" class="status"></div></div><div class="box"><h2>3 // PAGE PREVIEW</h2><div id="preview" class="preview"><p>No page yet. The dead kid is unionizing.</p></div></div><div class="box"><h2>4 // CONTINUITY CHECK</h2><div id="continuity"><p>Canon additions and continuity notes will appear after generation.</p></div><div class="btns"><button id="logout" class="btn dark">CLOSE STUDIO</button><a class="btn dark" href="./">READ THE COMIC</a></div></div></section></main><script>
const $=s=>document.querySelector(s),api='comic-api.php';let draft=null;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function jcall(action,data={}){const r=await fetch(api,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...data})});const j=await r.json().catch(()=>({ok:false,error:'Invalid server response'}));if(!r.ok||!j.ok)throw new Error(j.error||'Request failed');return j}function open(){ $('#login').classList.add('hidden');$('#workspace').classList.remove('hidden') }async function check(){try{const j=await jcall('session');if(j.authenticated)open()}catch{}}$('#loginBtn').onclick=async()=>{try{await jcall('login',{password:$('#password').value});open()}catch(e){$('#loginStatus').textContent=e.message}};
function loadDraft(d){draft=d;$('#plan').value=JSON.stringify(d.plan,null,2);$('#save').disabled=false;$('#render').disabled=false;$('#publish').disabled=d.status==='published';const c=d.plan;$('#continuity').innerHTML=`<span class="badge">${esc(c.continuity_note||'')}</span><h3>Possible canon additions</h3><p>${(c.canon_additions||[]).map(esc).join('<br>')||'None proposed.'}</p>`;renderScript(c);if(d.art_url)showArt(d.art_url)}function renderScript(p){$('#preview').innerHTML=`<h2>${esc(p.title)}</h2>${(p.panels||[]).map((x,i)=>`<div class="panelcard"><b>PANEL ${i+1}</b><p>${esc(x.visual)}</p><p><em>${esc(x.caption)}</em></p><p>“${esc(x.dialogue)}”</p></div>`).join('')}`;}function showArt(url){$('#preview').innerHTML=`<img src="${esc(url)}?v=${Date.now()}" alt="Generated Xander Zombie comic page"><p>Generated page draft. Script remains the canonical source.</p>`}
async function savePlan(){const plan=JSON.parse($('#plan').value);draft=(await jcall('save_plan',{id:draft.id,plan})).draft;loadDraft(draft);return draft}
$('#intake').onclick=async()=>{const fd=new FormData();fd.append('action','intake');fd.append('prompt',$('#prompt').value);for(const f of $('#files').files)fd.append('files[]',f);$('#status').textContent='Reading the mess, checking canon, writing panels…';$('#intake').disabled=true;try{const r=await fetch(api,{method:'POST',body:fd});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Generation failed');loadDraft(j.draft);$('#status').textContent='Draft generated. Nothing is canon until you publish it.'}catch(e){$('#status').textContent=e.message}finally{$('#intake').disabled=false}};
$('#save').onclick=async()=>{try{await savePlan();$('#draftStatus').textContent='Edits saved.'}catch(e){$('#draftStatus').textContent=e.message}};$('#render').onclick=async()=>{try{await savePlan();$('#draftStatus').textContent='Rendering an original comic page…';draft=(await jcall('render',{id:draft.id})).draft;loadDraft(draft);$('#draftStatus').textContent='Art generated. Review before publishing.'}catch(e){$('#draftStatus').innerHTML='<span class="danger">'+esc(e.message)+'</span>'}};$('#publish').onclick=async()=>{try{$('#publish').disabled=true;await savePlan();const r=await jcall('publish',{id:draft.id});draft.status='published';$('#draftStatus').textContent=`Published as Issue ${r.episode.issue}: ${r.episode.title}`;$('#publish').disabled=true}catch(e){$('#draftStatus').textContent=e.message;$('#publish').disabled=false}};$('#clear').onclick=()=>{$('#prompt').value='';$('#files').value='';$('#plan').value='';draft=null;$('#preview').innerHTML='<p>No page yet.</p>';$('#continuity').innerHTML='<p>No draft loaded.</p>';['#save','#render','#publish'].forEach(s=>$(s).disabled=true)};$('#logout').onclick=async()=>{await jcall('logout');location.reload()};check();
</script></body></html>